-- Реальные случаи из диспетчерского журнала за сентябрь 2026 (обезличены).
-- В тексте нет адресов, номеров лифтов и фамилий. Повторы одного кода сведены в одну запись с числом повторов в notes.
-- Код ищется по устройству УЛ ФБИР.484430.013, модель лифта в журнале не указана.

INSERT INTO cases (model_id, fault_code_id, occurred_on, description, cause_id, fix_id, outcome, notes, source)
SELECT NULL, fc.id, v.occurred_on, v.description, ca.id, fx.id, v.outcome, v.notes, v.source
FROM (
SELECT '43' AS code, '2026-09-23' AS occurred_on, 'Пассажиры застряли в кабине, на индикаторе УЛ код 43 (разомкнута цепь аппаратов безопасности). В записи названы СПК и ловители. Нижние вкладыши башмаков кабины заменены, ловители отрегулированы, лифт пущен.' AS description, 'Ослаблено крепление башмаков кабины или износ вкладышей' AS cause_title, 'Подтянуть крепление башмаков, заменить вкладыши' AS fix_title, 'resolved' AS outcome, 'Причина указана в записи техника. Кабина садилась на ловители, поэтому вместе с вкладышами регулировались и сами ловители.' AS notes, 'Журнал диспетчера, 2026-09-23, код 43, запись 1' AS source
    UNION ALL SELECT '43', '2026-09-04', 'Остановка между 1 и 2 этажами, на индикаторе код 43. Пассажиры освобождены. В записи как место поиска названы СПК и ловители. Лифт пущен.', NULL, NULL, 'resolved', 'Что именно найдено, в записи не сказано. Для кода 43 первым делом проверяют аппараты в цепи безопасности.', 'Журнал диспетчера, 2026-09-04, код 43, запись 2'
    UNION ALL SELECT '46', '2026-09-12', 'Пассажиры застряли у этажа 0, код 46 (разомкнута блокировочная цепь контроля дверей кабины). Выполнен перезапуск устройства, лифт заработал, пассажиры освобождены.', NULL, NULL, 'resolved', 'Причина не установлена. Перезапуск убирает следствие, но не причину: при повторах смотреть контакты дверей кабины.', 'Журнал диспетчера, 2026-09-12, код 46, запись 3'
    UNION ALL SELECT 'C6', '2026-09-23', 'Пассажиры застряли у этажа 1. В УЛ код 44 с подсказкой C6 (узел «1ДШ» платы ПТЗ выдал логический 0 в зоне остановки). Пассажиры освобождены, лифт пущен.', NULL, NULL, 'resolved', 'Подсказка C6 встретилась три раза за месяц (9, 21 и 23 сентября), то есть случай повторяющийся.', 'Журнал диспетчера, 2026-09-23, код C6, запись 4'
    UNION ALL SELECT 'C0', '2026-09-16', 'Пассажиры застряли у этажа 5. Код 44 с подсказкой C0: цепь контроля дверей шахты разомкнута вне зоны точной остановки. Пассажиры освобождены, лифт пущен.', NULL, NULL, 'resolved', 'C0 встретилась дважды за месяц (10 и 16 сентября). Сначала проверяют контакты и замки дверей шахты.', 'Журнал диспетчера, 2026-09-16, код C0, запись 5'
    UNION ALL SELECT 'C1', '2026-09-05', 'Пассажиры застряли у этажа 8. Код 44 с подсказкой C1: цепь контроля дверей кабины разомкнута вне зоны точной остановки. Пассажиры освобождены, лифт пущен.', NULL, NULL, 'resolved', 'Подсказка C1 в этом месяце одна. Проверяют контакты и отводку двери кабины.', 'Журнал диспетчера, 2026-09-05, код C1, запись 6'
    UNION ALL SELECT 'C7', '2026-09-28', 'Лифт не работает, в УЛ код 44 с подсказкой C7 (узел «1ДШ» платы ПТЗ выдал логическую 1 в зоне остановки). Лифт пущен.', NULL, NULL, 'resolved', 'В отличие от C6 здесь узел выдал единицу. Что было сделано, в записи не указано.', 'Журнал диспетчера, 2026-09-28, код C7, запись 7'
    UNION ALL SELECT 'A2', '2026-09-04', 'Лифт не работает, на индикаторе код A2 (двери шахты открыты дольше контрольного времени), рядом отмечена ошибка 44. Лифт пущен.', NULL, NULL, 'resolved', 'Код A2 был в журнале четыре раза за месяц на этажах 1–3, то есть проблема повторяющаяся. Проверять замки и состояние порогов дверей шахты.', 'Журнал диспетчера, 2026-09-04, код A2, запись 8'
    UNION ALL SELECT '50', '2026-09-11', 'Лифт не работает, код 50 (превышено контрольное время закрытия дверей), этаж 6. Лифт пущен.', NULL, NULL, 'resolved', 'Код 50 самый частый после 99 в рабочих неисправностях: семь раз за месяц на разных этажах. Повторы говорят о регулировке привода дверей или о препятствии на порогах.', 'Журнал диспетчера, 2026-09-11, код 50, запись 9'
    UNION ALL SELECT '50', '2026-09-07', 'Лифт не работает, код 50. В записи рядом указано FF. Лифт пущен.', NULL, NULL, 'resolved', 'Что означает FF, в базе не подтверждено, значение не придумываем.', 'Журнал диспетчера, 2026-09-07, код 50, запись 10'
    UNION ALL SELECT '48', '2026-09-30', 'Лифт не работает, на индикаторе код 48 (восемь реверсов дверей подряд), этаж 4. Лифт пущен.', NULL, NULL, 'resolved', 'Реверсы дверей чаще всего вызывает препятствие в проёме или неисправный выключатель реверса.', 'Журнал диспетчера, 2026-09-30, код 48, запись 11'
    UNION ALL SELECT '90', '2026-09-19', 'Вызов по пожарной сигнализации, на индикаторе код 90 (нарушен контроль фаз питающей сети). Лифт пущен.', NULL, NULL, 'resolved', 'Код 90 встретился три раза за месяц (4, 5 и 19 сентября). При повторах проверяют фазы на вводе и автоматы питания.', 'Журнал диспетчера, 2026-09-19, код 90, запись 12'
    UNION ALL SELECT '99', '2026-10-01', 'Вызов по сигналу пожарной автоматики АПС и ПДЗ, в УЛ код 99. На месте выполнен сброс, лифт пущен.', NULL, NULL, 'resolved', 'Код 99 самый частый: 25 записей из 68 за месяц. Почти все связаны с сигналом пожарной автоматики, а не с поломкой лифта.', 'Журнал диспетчера, 2026-10-01, код 99, запись 13'
    UNION ALL SELECT '99', '2026-09-24', 'Вызов по сигналу АПС и ПДЗ, код 99. По приезду лифт работал, вызов отменён.', NULL, NULL, 'resolved', 'Сигнал пожарной автоматики снят сам. Это ложное или кратковременное срабатывание, неисправности лифта нет.', 'Журнал диспетчера, 2026-09-24, код 99, запись 14'
    UNION ALL SELECT '', '2026-09-15', 'Пассажиры застряли в кабине. Заменена плата ПТЗ, лифт пущен.', NULL, NULL, 'resolved', 'Причина указана по записи техника: плата ПТЗ. Код в записи не отмечен.', 'Журнал диспетчера, 2026-09-15, без кода, запись 15'
    UNION ALL SELECT '', '2026-09-05', 'Заявка электромеханику: двери закрываются слишком быстро. Залипла кнопка закрытия дверей, кнопка заменена.', NULL, NULL, 'resolved', 'Тип привода дверей в записи не указан.', 'Журнал диспетчера, 2026-09-05, без кода, запись 16'
    UNION ALL SELECT '', '2026-09-09', 'Лифт не работает. Выполнена чистка контактов дверей шахты, лифт пущен.', NULL, NULL, 'resolved', 'Загрязнённые контакты цепи дверей шахты дают сообщения вроде 44, A2 или 46.', 'Журнал диспетчера, 2026-09-09, без кода, запись 17'
    UNION ALL SELECT '', '2026-09-05', 'Заявка электромеханику: почистить пороги всех этажей. Выполнена чистка порогов кабины и шахты.', NULL, 'Очистить пороги кабины и шахты', 'resolved', 'Профилактика после серии отказов дверей.', 'Журнал диспетчера, 2026-09-05, без кода, запись 18'
    UNION ALL SELECT '', '2026-09-12', 'Заявка электромеханику: лифт останавливается выше или ниже посадочной площадки, сработал контроль перегрузки при трёх пассажирах. Проверено весовое устройство.', NULL, NULL, 'resolved', 'Текст записи обрезан, итог по исходу записан как «Выполнено». Неточная остановка и ложная перегрузка вместе указывают на весовое устройство.', 'Журнал диспетчера, 2026-09-12, без кода, запись 19'
    UNION ALL SELECT '', '2026-09-17', 'Пассажиры застряли у этажа 1. Потребовался ремонт двери кабины, ремонт выполнен, лифт пущен.', NULL, NULL, 'resolved', 'Что именно отремонтировано, в записи не сказано.', 'Журнал диспетчера, 2026-09-17, без кода, запись 20'
    UNION ALL SELECT '', '2026-09-02', 'Лифт не работает, в записи «Err 30» (код другой системы). Выполнена регулировка приводов двери кабины, лифт пущен.', NULL, NULL, 'resolved', 'Коды вида Err и Er принадлежат другой системе управления, значение в базе не подтверждено и с кодами УЛ не связано.', 'Журнал диспетчера, 2026-09-02, без кода, запись 21'
    UNION ALL SELECT '', '2026-09-03', 'Пассажиры застряли у этажа 1, в записи «Er 55 GLZ» (код другой системы). Замок двери шахты 1 этажа отключён, пассажиры освобождены.', NULL, NULL, 'resolved', 'Код не связан с кодами УЛ, значение не подтверждено. Отключённый замок двери шахты нужно после работ вернуть в нормальное состояние.', 'Журнал диспетчера, 2026-09-03, без кода, запись 22'
    UNION ALL SELECT '', '2026-09-19', 'Пассажиры застряли у этажа 0, в записи «Er 101» и «Er 55 GLZ» (коды другой системы). Створка двери кабины не сложилась. Пассажиры освобождены.', NULL, NULL, 'resolved', 'Коды не связаны с кодами УЛ, значение не подтверждено.', 'Журнал диспетчера, 2026-09-19, без кода, запись 23'
) v
LEFT JOIN controllers c ON c.name = 'УЛ ФБИР.484430.013 (ГОСТ 33984.1, автоматические двери)'
LEFT JOIN fault_codes fc ON fc.controller_id = c.id AND fc.code = v.code AND v.code <> ''
LEFT JOIN causes ca ON ca.title = v.cause_title
LEFT JOIN fixes fx ON fx.title = v.fix_title
ON DUPLICATE KEY UPDATE fault_code_id = VALUES(fault_code_id), occurred_on = VALUES(occurred_on), description = VALUES(description), cause_id = VALUES(cause_id), fix_id = VALUES(fix_id), outcome = VALUES(outcome), notes = VALUES(notes);
